// Calculate last week's date
const now = new Date();
const lastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return {
  json: {
    lastWeek: lastWeek.toISOString(),
    now: now.toISOString()
  }
};

// Aggregate data from GitHub
const commits = $input.all()[0].json;
const issues = $input.all()[1].json;
const prs = $input.all()[2].json;

const language = $env.LANGUAGE || 'EN';

let prompt = language === 'FR' 
  ? `Génère un résumé hebdomadaire pour le dépôt ${$env.GITHUB_OWNER}/${$env.GITHUB_REPO}:

`
  : `Generate a weekly summary for the repository ${$env.GITHUB_OWNER}/${$env.GITHUB_REPO}:

`;

// Add commits info
if (commits && commits.length > 0) {
  prompt += language === 'FR' 
    ? `Commits (${commits.length}):
`
    : `Commits (${commits.length}):
`;
  commits.slice(0, 10).forEach(c => {
    prompt += `- ${c.message}
`;
  });
  if (commits.length > 10) {
    prompt += language === 'FR' ? `- ... et ${commits.length - 10} autres
` : `- ... and ${commits.length - 10} more
`;
  }
  prompt += '
';
}

// Add issues info
if (issues && issues.length > 0) {
  prompt += language === 'FR'
    ? `Issues fermées (${issues.length}):
`
    : `Closed Issues (${issues.length}):
`;
  issues.slice(0, 5).forEach(i => {
    prompt += `- #${i.number}: ${i.title}
`;
  });
  if (issues.length > 5) {
    prompt += language === 'FR' ? `- ... et ${issues.length - 5} autres
` : `- ... and ${issues.length - 5} more
`;
  }
  prompt += '
';
}

// Add PRs info
if (prs && prs.length > 0) {
  prompt += language === 'FR'
    ? `Pull Requests fusionnées (${prs.length}):
`
    : `Merged Pull Requests (${prs.length}):
`;
  prs.slice(0, 5).forEach(p => {
    prompt += `- #${p.number}: ${p.title}
`;
  });
  if (prs.length > 5) {
    prompt += language === 'FR' ? `- ... et ${prs.length - 5} autres
` : `- ... and ${prs.length - 5} more
`;
  }
  prompt += '
';
}

prompt += language === 'FR'
  ? 'Rédige un résumé narratif engageant de l\'activité de cette semaine.'
  : 'Write an engaging narrative summary of this week\'s activity.';

return {
  json: {
    prompt: prompt,
    commitCount: commits?.length || 0,
    issueCount: issues?.length || 0,
    prCount: prs?.length || 0
  }
};

// Format summary for Discord
const summary = $input.all()[0].json.content;
const language = $env.LANGUAGE || 'EN';

const title = language === 'FR' 
  ? `📊 Résumé Hebdomadaire - ${$env.GITHUB_REPO}`
  : `📊 Weekly Summary - ${$env.GITHUB_REPO}`;

const content = `${title}

${summary}`;

return {
  json: {
    content: content
  }
};
